function normaliseEpisodes(source){
 const normal=(Array.isArray(source)?source:[]).map(x=>({...x,seasonNo:+x.seasonNo||1,isSpecial:+x.seasonNo===99||x.isSpecial===true}));
 const existingSpecialNos=new Set(normal.filter(isSpecialEpisode).map(x=>+x.episodeNo||0));
 SPECIAL_EPISODES.forEach(x=>{if(!existingSpecialNos.has(+x.episodeNo||0))normal.push({...x});});
 return normal;
}
function applyEpisodeOneUpgrade(){const ep1=items.find(x=>x.episodeNo===1&&!isSpecialEpisode(x));if(ep1&&ep1.version!=='v1.0'){ep1.scriptZh=EP01_DETAILED_ZH;ep1.scriptEn=EP01_DETAILED_EN;ep1.summaryZh='Angeline相信钱能解决一切，入住第一天却发现，钱可以买东西，却不能让已经签下的房间变大，也不能让合同和共同生活规则自动消失。';ep1.summaryEn='Angeline believes money can solve anything, but on move-in day she learns that it cannot enlarge a signed-for room, erase a tenancy agreement, or override the rules of shared living.';ep1.culturePointZh='新加坡HDB租房实景、房源广角照片、租约责任、共享空间与消防通道意识。';ep1.culturePointEn='Singapore HDB room rentals, wide-angle listing photos, tenancy responsibilities, shared spaces and clear escape routes.';ep1.scriptStatus='final';ep1.productionStage='locked';ep1.progress=90;ep1.openIssues='确认超大行李箱、虚构租约、卷尺、超长入住规则纸及拍摄排期';ep1.openIssuesEn='Confirm the oversized suitcase, fictional tenancy agreement, measuring tape, extra-long house-rules sheet and shoot schedule.';ep1.version='v1.0';return ep1;}return null;}
async function fetchEpisodesWithTimeout(timeoutMs=2500){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeoutMs);try{const r=await fetch('/api/episodes',{cache:'no-store',signal:controller.signal});if(!r.ok)return [];const d=await r.json();return Array.isArray(d.episodes)?d.episodes:[];}catch(e){return [];}finally{clearTimeout(timer);}}
function load({force=false}={}){
  // Reuse the in-memory episode dataset when navigating between episode-related pages.
  // This prevents every route change from requesting and parsing the full D1 payload again.
  if(loaded&&!force){renderCurrent();return Promise.resolve(items);}
  if(loadPromise&&!force){return loadPromise.then(()=>{renderCurrent();return items;});}

  loadPromise=(async()=>{
    // Paint immediately from local cache (or bundled defaults). D1 must never block the first screen.
    if(!loaded||force){
      let local=[];try{local=JSON.parse(localStorage.getItem('uorEpisodes')||'[]');}catch(e){}
      items=normaliseEpisodes(local.length?local:DEFAULT_EPISODES.map(x=>({...x})));
      const baselineKey='uorWorkflowBaselineV75';
      const baselineNeeded=localStorage.getItem(baselineKey)!=='done';
      if(baselineNeeded){items=items.map(x=>({...x,scriptStatus:'idea',productionStage:'outline',progress:0,shootDate:'',publishDate:'',openIssues:'等待大纲确认',openIssuesEn:'Awaiting outline approval'}));localStorage.setItem(baselineKey,'done');}
      const upgraded=applyEpisodeOneUpgrade();
      loaded=true;setLocal();renderCurrent();

      // Start one background reconciliation only. Route changes reuse the same in-memory data.
      if(!syncStarted||force){
        syncStarted=true;
        const sync=async()=>{
          const remote=await fetchEpisodesWithTimeout();
          if(remote.length){
            const next=normaliseEpisodes(remote);
            const changed=JSON.stringify(next)!==JSON.stringify(items);
            if(changed){items=next;applyEpisodeOneUpgrade();setLocal();renderCurrent();}
          }else if(!force){
            try{await fetch('/api/episodes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({episodes:items})});}catch(e){}
          }
          if(upgraded){try{fetch('/api/episodes',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(upgraded)});}catch(e){}}
          return items;
        };
        if('requestIdleCallback' in window){
          requestIdleCallback(()=>sync().catch(()=>{}),{timeout:900});
        }else{
          setTimeout(()=>sync().catch(()=>{}),0);
        }
      }
    }
    return items;
  })();

  return loadPromise.finally(()=>{loadPromise=null;});
}
const episodeChannel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('uor-episodes'):null;function setLocal(){localStorage.setItem('uorEpisodes',JSON.stringify(items));window.dispatchEvent(new CustomEvent('uor:episodes-updated'));}function announceEpisodeUpdate(){episodeChannel?.postMessage({type:'updated'});}episodeChannel?.addEventListener('message',async e=>{if(e.data?.type!=='updated')return;const remote=await fetchEpisodesWithTimeout(1800);if(remote.length){items=normaliseEpisodes(remote);setLocal();renderCurrent();}});
